/**
 * A metric over a date range with a drill-down. The overview reads one governed metric grouped by
 * a dimension and draws it as a bar chart; clicking a bar opens the records view with the group and
 * the range in the URL, so the drill-down is a link the viewer can share. The provenance footer
 * cites the metric.
 *
 * Budget: every `Chart*` primitive shares one engine (recharts), so mixing chart types adds no second engine to the 2 MiB bundle cap.
 */
import { createRoot } from 'react-dom/client';
import {
  Activity,
  AlertCard,
  Button,
  ChartLine,
  Grid,
  PageHeader,
  Stack,
  StatGroup,
  ChartBar,
  DateRangePicker,
  EmptyState,
  ProvenanceFooter,
  Section,
  Skeleton,
  SurfaceApp,
  Table,
  parseAsIsoDate,
  parseAsString,
  useMetric,
  useNavigation,
  useQuery,
  useQueryState,
  useSurfaceApp,
} from '@cynap/surface-sdk';

import './styles.css';

/** The metric, the dimension it is grouped by, and the entity type behind it. Replace all three. */
const METRIC_NAME = 'REPLACE_WITH_METRIC_NAME';
const GROUP_BY = 'REPLACE_WITH_DIMENSION';
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
/** The portal path of this Surface's landing route: `/data/` plus its `path` in routes.json. */
const MOUNT_PATH = '/data/replace-with-landing-path';

type Row = Record<string, unknown>;
const isRecord = (value: unknown): value is Row => typeof value === 'object' && value !== null && !Array.isArray(value);
/**
 * A grouped metric row is `{label, value}`: the group's value is `label`, never a key named after
 * the dimension. A metric grouped by two dimensions labels each row `"<a> / <b>"`.
 */
const labelOf = (row: Row) => String(row.label ?? '');
const valueOf = (row: Row) => (typeof row.value === 'number' ? row.value : Number(row.value) || 0);

function useRange() {
  const [from, setFrom] = useQueryState('from', parseAsIsoDate);
  const [to, setTo] = useQueryState('to', parseAsIsoDate);
  return { from, to, setFrom, setTo };
}

/** `YYYY-MM-DD` ↔ a UTC midnight `Date`, for the picker. */
const toDate = (day: string | null) => (day ? new Date(`${day}T00:00:00Z`) : undefined);
const toDay = (date: Date | undefined) => (date ? date.toISOString().slice(0, 10) : null);

function Overview() {
  const { navigate } = useNavigation();
  const range = useRange();
  const metric = useMetric(METRIC_NAME, {
    group_by: GROUP_BY,
    ...(range.from ? { date_from: range.from } : {}),
    ...(range.to ? { date_to: range.to } : {}),
  });

  function drill(group: string) {
    const query = new URLSearchParams({ group });
    if (range.from) query.set('from', range.from);
    if (range.to) query.set('to', range.to);
    navigate(`${MOUNT_PATH}/records?${query.toString()}`);
  }

  const chartRows = (metric.data?.rows ?? []).map((row) => ({ group: labelOf(row) || '(none)', value: valueOf(row) }));
  const activity = useQuery('knowledge_query_data', { tool: 'knowledge_recent_activity', params: { entity_type: ENTITY_TYPE, limit: 10 } }, { parse: readActivity });
  return (
    <Stack id="overview-page" config={{ gap: 24 }}>
      <PageHeader title="Overview" description="The period at a glance, with the records behind each number." />
      <DateRangePicker
        value={{ from: toDate(range.from), to: toDate(range.to) }}
        onChange={(next) => {
          range.setFrom(toDay(next.from));
          range.setTo(toDay(next.to));
        }}
      />
      {/* pattern:overview:start */}
      {metric.state === 'loading' ? <Grid id="overview-loading" config={{ cols: { base: 1, md: 2 }, gap: 24 }}>
        <Skeleton primitiveKind="StatGroup" height={120} /><Skeleton primitiveKind="Chart.Bar" height={240} /><Skeleton primitiveKind="Chart.Line" height={240} />
      </Grid> : metric.state === 'error' || metric.state === 'denied' ? <Stack id="overview-error" config={{ gap: 16 }}>
        <AlertCard severity="error" title="Summary unavailable" description="Try reading the period again." /><Button variant="outline" onClick={metric.refresh}>Retry</Button>
      </Stack> : chartRows.length === 0 ? <EmptyState title="No data in this range" description="Choose another period or refresh." action={{ label: 'Refresh', onClick: metric.refresh }} /> : <>
        <StatGroup items={[
          { label: 'Total', value: chartRows.reduce((sum, row) => sum + row.value, 0) },
          { label: 'Groups', value: chartRows.length },
          { label: 'Largest group', value: Math.max(...chartRows.map((row) => row.value)) },
        ]} />
        <Grid id="overview-charts" config={{ cols: { base: 1, md: 2 }, gap: 24 }}>
          <Section title="By group"><ChartBar data={chartRows} xAxisKey="group" yAxisKeys={['value']} onSegmentClick={(point) => drill(String(point.group ?? ''))} /></Section>
          <Section title="Group profile" description="Groups in the metric's order, not a time series."><ChartLine data={chartRows} xAxisKey="group" yAxisKeys={['value']} /></Section>
        </Grid>
      </>}
      <Section title="Recent activity">
        {activity.state === 'loading' ? <Skeleton primitiveKind="Activity" height={200} />
        : activity.state === 'error' || activity.state === 'denied' ? <Stack id="activity-error" config={{ gap: 16 }}>
          <AlertCard severity="error" title="Activity unavailable" /><Button variant="outline" onClick={activity.refetch}>Retry</Button>
        </Stack> : !activity.data?.length ? <EmptyState title="No recorded activity" description="Refresh after the next record change." action={{ label: 'Refresh', onClick: activity.refetch }} />
        : <Activity items={activity.data} />}
      </Section>
      {/* pattern:overview:end */}
      {metric.provenance && (
        <ProvenanceFooter metricName={METRIC_NAME} dataAsOf={metric.provenance.dataAsOf} sampleN={metric.provenance.sampleN} />
      )}
    </Stack>
  );
}

function readRows(payload: unknown): Row[] | null {
  return isRecord(payload) && Array.isArray(payload.rows) ? payload.rows.filter(isRecord) : null;
}

function readActivity(payload: unknown) {
  if (!isRecord(payload) || !Array.isArray(payload.rows)) return null;
  return payload.rows.filter(isRecord).map((item) => ({ type: String(item.type ?? 'updated'), entityName: String(item.name ?? 'Record'), action: String(item.content ?? 'Record changed'), timestamp: String(item.created_at ?? ''), entityType: String(item.entity_type ?? ENTITY_TYPE) }));
}

function Records() {
  const [group] = useQueryState('group', parseAsString);
  const records = useQuery(
    'knowledge_query_data',
    { tool: 'knowledge_advanced_query', params: { entity_type: ENTITY_TYPE, filter: { [GROUP_BY]: group ?? '' }, limit: 50 } },
    { parse: readRows, enabled: group !== null }
  );
  return (
    <main className="tpl-page">
      <PageHeader title="Records" description="The records behind this group." />
      <Section title={group ?? 'Records'}>
        {records.state === 'error' || records.state === 'denied' ? <Stack id="drill-error" config={{ gap: 16 }}>
          <AlertCard severity="error" title="Records unavailable" /><Button variant="outline" onClick={records.refetch}>Retry</Button>
        </Stack> : records.state === 'loading' ? <Skeleton primitiveKind="Table" height={240} /> : !records.data?.length ?
          <EmptyState title="No records in this group" action={{ label: 'Refresh', onClick: records.refetch }} /> : <Table
          columns={[{ accessorKey: 'name', header: 'Name' }]}
          data={(records.data ?? []).map((record) => ({ name: String(record.name ?? record.id) }))}
          isLoading={records.state === 'loading'}
        />}
      </Section>
    </main>
  );
}

function CurrentView() {
  const { routeInput } = useSurfaceApp();
  if (routeInput === null) return null;
  return routeInput.view === 'records' ? <Records /> : <Overview />;
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'overview', version: '1.0.0' }}>
      <CurrentView />
    </SurfaceApp>
  );
}

